namespace Molinex.Platform.Shared.Domain.Model.Aggregates;

/// <summary>
///     Base aggregate. Events are registered as factories so identifiers generated by the database
///     are already assigned when the events are built for dispatch.
/// </summary>
public abstract class AggregateRoot : IAggregateRoot
{
    private readonly List<Func<IEvent>> _domainEventFactories = [];

    public IReadOnlyCollection<IEvent> DomainEvents =>
        _domainEventFactories.Select(factory => factory()).ToList().AsReadOnly();

    public void ClearDomainEvents() => _domainEventFactories.Clear();

    protected void AddDomainEvent(Func<IEvent> domainEventFactory) => _domainEventFactories.Add(domainEventFactory);
}
